        soldOutState = new SoldOutState(this);
        noQuarterState = new NoQuarterState(this);
        hasQuarterState = new HasQuarterState(this);
        soldState = new SoldState(this);
        state = count > 0 ? noQuarterState : soldOutState;
    }
    void setState(State* s) { state = s; }
    State* getHasQuarterState() { return hasQuarterState; }
    State* getNoQuarterState() { return noQuarterState; }
    State* getSoldState() { return soldState; }
    State* getSoldOutState() { return soldOutState; }
    int getCount() { return count; }
    void releaseTissue() { if (count > 0) --count; }
    void insertQuarter() { state->insertQuarter(); report("insert"); }
    void ejectQuarter() { state->ejectQuarter(); report("eject"); }
    void turnCrank() { state->turnCrank(); state->dispense(); report("crank"); }
    void report(const char* action) { cout << action << " -> " << state->name() << " (count " << count << ")" << endl; }
